={
  "model": "llama3.2:3b",
  "system": "Você é o Roteirista & Engenheiro de Prompt de vídeos curtos. Crie um roteiro de 15 segundos em 3 blocos: hook (0-3s, max 14 palavras), body (3-12s, 15-25 palavras) e cta (12-15s, 4-10 palavras). Para cada cena, crie um prompt em inglês para imagem (SDXL) com iluminação dramática e vertical 9:16 aspect ratio. Responda ESTRITAMENTE em JSON seguindo o schema: {\"topic\": \"...\", \"style\": \"...\", \"targetDuration\": \"15s\", \"totalWordCount\": 38, \"scenes\": [{\"order\": 1, \"type\": \"hook\", \"timeRange\": \"0-3s\", \"narrationText\": \"...\", \"imagePromptEnglish\": \"... vertical 9:16 aspect ratio\"}, {\"order\": 2, \"type\": \"body\", \"timeRange\": \"3-12s\", \"narrationText\": \"...\", \"imagePromptEnglish\": \"... 9:16\"}, {\"order\": 3, \"type\": \"cta\", \"timeRange\": \"12-15s\", \"narrationText\": \"...\", \"imagePromptEnglish\": \"... 9:16\"}], \"fullNarration\": \"...\"}",
  "prompt": "{{ 'Tema: ' + ($json.body.topic || 'Como a IA gera vídeos virais em segundos') + '. Estilo visual: ' + ($json.body.style || 'Cyberpunk') }}",
  "format": "json",
  "stream": false,
  "options": {
    "temperature": 0.7
  }
}

parameters.jsCode:
const inputData = $('Webhook - /webhook/generate-script').first().json.body || {};
const topic = inputData.topic || 'Como a IA cria vídeos em segundos';
const style = inputData.style || 'Cyberpunk';

let scriptData = null;
try {
  const raw = $input.first().json.response;
  if (raw) {
    scriptData = typeof raw === 'string' ? JSON.parse(raw.replace(/^```json\s*|\s*```$/g, '')) : raw;
  }
} catch (e) {}

if (!scriptData || !scriptData.scenes || scriptData.scenes.length < 3) {
  scriptData = {
    topic: topic,
    style: style,
    targetDuration: '15s',
    totalWordCount: 35,
    scenes: [
      {
        order: 1,
        type: 'hook',
        timeRange: '0-3s',
        narrationText: `Você sabia disso sobre ${topic}?`,
        imagePromptEnglish: `Dramatic high contrast opening visual capturing ${topic}, glowing cinematic lighting, ${style.toLowerCase()} aesthetic, 8k render, vertical 9:16 aspect ratio`
      },
      {
        order: 2,
        type: 'body',
        timeRange: '3-12s',
        narrationText: `Esse detalhe surpreendente sobre ${topic} muda completamente a forma como a maioria das pessoas enxerga o assunto.`,
        imagePromptEnglish: `Detailed dynamic action scene illustrating ${topic}, cinematic volumetric lighting, ${style.toLowerCase()} style, 8k, 9:16 aspect ratio`
      },
      {
        order: 3,
        type: 'cta',
        timeRange: '12-15s',
        narrationText: 'Qual a sua opinião sobre isso? Deixe seu comentário!',
        imagePromptEnglish: `Inspiring closing visual of ${topic} with dramatic atmospheric lighting, ${style.toLowerCase()} aesthetic, 8k, vertical 9:16`
      }
    ],
    fullNarration: `Você sabia disso sobre ${topic}? Esse detalhe surpreendente sobre ${topic} muda completamente a forma como a maioria das pessoas enxerga o assunto. Qual a sua opinião sobre isso? Deixe seu comentário!`
  };
}

return [{ json: { inputData, script: scriptData } }];

