parameters.jsCode:
const script = $('Code - Validate Script & Fallback').first().json.script;
let growth = null;

try {
  const raw = $input.first().json.response;
  if (raw) {
    growth = typeof raw === 'string' ? JSON.parse(raw.replace(/^```json\s*|\s*```$/g, '')) : raw;
  }
} catch (e) {}

if (!growth || !growth.title) {
  growth = {
    title: `A verdade impressionante sobre ${script.topic}`.slice(0, 65),
    description: `Descubra os fatos e segredos por trás de ${script.topic}. Assista até o final e comente sua opinião! #viral`,
    callToActionQuestion: 'Você já sabia disso?',
    hashtags: ['#fyp', '#viral', '#curiosidades', '#aprendanotiktok', '#fatos', '#trending'],
    suggestedAudioVibe: 'Trending Cinematic Bass 120BPM',
    retentionStrategyTip: 'Fixe o primeiro comentário respondendo sua própria pergunta para estimular o debate.'
  };
}

return [{
  json: {
    success: true,
    script: script,
    growth: growth,
    mediaPrompts: script.scenes.map(s => ({
      order: s.order,
      timeRange: s.timeRange,
      narration: s.narrationText,
      prompt: s.imagePromptEnglish
    }))
  }
}];
